{"implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])
    by_id = {}
    children_of = {}
    for node in nodes:
        nid = node['id']
        by_id[nid] = node
        children_of[nid] = []
    root_id = None
    for node in nodes:
        pid = node['parent']
        if pid is None:
            root_id = node['id']
        else:
            children_of[pid].append(node['id'])
    retained = set(by_id.keys())
    sorted_ids = sorted(by_id.keys(), key=lambda nid: (-by_id[nid]['depth'], nid))
    removed = []
    for nid in sorted_ids:
        node = by_id[nid]
        if nid == root_id:
            continue
        if node['symbol'] in required_symbols:
            continue
        if not node['removable']:
            continue
        if any(child in retained for child in children_of[nid]):
            continue
        removed.append(nid)
        retained.remove(nid)
    retained_sorted = sorted(retained)
    return {'removed_node_ids': removed, 'retained_node_ids': retained_sorted}"}
